<?php $title='Calendar';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>Calendar & Reminders</h1><p>Schedule reminders for one or many clients and review them by date.</p></div></div><div class="calendar-grid"><section class="panel"><label>Date<input id="calendarDate" type="date" value="<?=date('Y-m-d')?>"></label><div id="reminders"></div></section><section class="panel"><form id="reminderForm"><h2>Add reminder</h2><?=csrf_field()?><label>Title<input name="title" required></label><label>Description<textarea name="description" rows="3"></textarea></label><label>Date & time<input name="reminder_at" type="datetime-local" required></label><label>Type<select name="reminder_type"><option>general</option><option>missing_document</option><option>deadline</option><option>follow_up</option></select></label><label>Recurrence<select name="recurrence_type" id="recurrenceType"><option value="none">Does not repeat</option><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option><option value="custom">Custom interval</option></select></label><div id="recurrenceFields" class="form-grid" style="display:none"><label>Repeat every<input type="number" min="1" value="1" name="recurrence_interval"></label><label>Unit<select name="recurrence_unit"><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option></select></label><label>End date<input type="date" name="recurrence_end_date"></label></div><label>Assigned user<select name="assigned_user_id"><option value="">Current user</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'])?></option><?php endforeach;?></select></label><label>Clients</label><div class="client-picker"><input id="clientSearch" placeholder="Search clients"><div id="clientResults"></div><div id="selectedClients" class="selected-list"></div><input type="hidden" name="client_ids[]" id="clientIds"></div><input type="hidden" name="reminder_id" id="reminderId"><button class="primary" id="reminderSubmit">Done</button><button type="button" class="secondary" id="cancelEdit" style="display:none">Cancel edit</button></form></section></div><?php require __DIR__.'/../layouts/footer.php';?>
